-- Incremental patch for the existing disposable Slotzy test project only.
-- Apply manually in that project's SQL editor; do not run against staging/prod.
begin;

-- The original RPC reused generic record names and unqualified identifiers.
-- Reinstall the corrected definition from the reviewed canonical schema.
create or replace function public.slotzy_legacy_target_id(p_entity_type text, p_source_id text)
returns uuid language plpgsql security definer set search_path = public as $$
declare target uuid;
begin
  if coalesce(btrim(p_source_id), '') = '' then raise exception 'legacy source id is required for %', p_entity_type; end if;
  select target_id into target from public.legacy_source_ids where entity_type = p_entity_type and source_id = p_source_id;
  if target is null and p_entity_type = 'user' then
    select u.id into target from public.users u where u.id::text = p_source_id;
    if target is not null then
      insert into public.legacy_source_ids (entity_type, source_id, target_id, is_canonical)
      values ('user', p_source_id, target, not exists (select 1 from public.legacy_source_ids l where l.entity_type = 'user' and l.target_id = target and l.is_canonical))
      on conflict (entity_type, source_id) do update set target_id = excluded.target_id;
    end if;
  end if;
  if target is null then
    target := gen_random_uuid();
    insert into public.legacy_source_ids (entity_type, source_id, target_id) values (p_entity_type, p_source_id, target);
  end if;
  return target;
end;
$$;

create or replace function public.slotzy_storage_write_snapshot(snapshot jsonb)
returns void language plpgsql security definer set search_path = public as $$
declare
  v_user jsonb; v_shop jsonb; v_service jsonb; v_booking jsonb; v_time_off jsonb;
  v_schedule jsonb; v_day_schedule jsonb; v_username text; v_day_name text;
  v_user_id uuid; v_shop_id uuid; v_member_id uuid; v_service_id uuid; v_booking_id uuid;
  v_source text; v_provider_source text; v_starts timestamptz; v_ends timestamptz; v_duration integer;
begin
  if jsonb_typeof(snapshot) <> 'object' then raise exception 'snapshot must be an object'; end if;
  for v_user in select e.value from jsonb_array_elements(coalesce(snapshot->'users', '[]'::jsonb)) e(value) loop
    v_source := coalesce(nullif(v_user->>'id',''),v_user->>'username'); v_user_id := public.slotzy_legacy_target_id('user',v_source);
    insert into public.users (id,username,display_name,password_hash,role,email,phone,created_at) values (v_user_id,v_user->>'username',coalesce(nullif(v_user->>'displayName',''),v_user->>'username'),coalesce(v_user->>'passwordHash',''),coalesce((v_user->>'role')::public.user_role,'customer'),nullif(v_user->>'email','')::citext,nullif(v_user->>'phone',''),coalesce(nullif(v_user->>'createdAt','')::timestamptz,now())) on conflict (id) do update set username=excluded.username,display_name=excluded.display_name,password_hash=excluded.password_hash,role=excluded.role,email=excluded.email,phone=excluded.phone,deleted_at=null;
    if v_source <> v_user->>'username' then insert into public.legacy_source_ids(entity_type,source_id,target_id,is_canonical) values ('user',v_user->>'username',v_user_id,false) on conflict(entity_type,source_id) do update set target_id=excluded.target_id; end if;
  end loop;
  for v_shop in select e.value from jsonb_array_elements(coalesce(snapshot->'shops','[]'::jsonb)) e(value) loop
    v_source:=v_shop->>'id'; v_shop_id:=public.slotzy_legacy_target_id('shop',v_source); select l.target_id into v_user_id from public.legacy_source_ids l where l.entity_type='user' and l.source_id=v_shop->>'ownerUsername'; if v_user_id is null then raise exception 'shop % references unknown owner %',v_source,v_shop->>'ownerUsername'; end if;
    insert into public.shops(id,owner_user_id,name,slug,phone,email,logo_url,cover_url,created_at) values(v_shop_id,v_user_id,coalesce(v_shop->>'name',v_shop->>'businessName'),v_shop->>'slug',nullif(v_shop->>'shopPhone',''),nullif(v_shop->>'shopEmail','')::citext,nullif(v_shop->>'logo',''),nullif(v_shop->>'cover',''),coalesce(nullif(v_shop->>'createdAtISO','')::timestamptz,now())) on conflict(id) do update set owner_user_id=excluded.owner_user_id,name=excluded.name,slug=excluded.slug,phone=excluded.phone,email=excluded.email,logo_url=excluded.logo_url,cover_url=excluded.cover_url,deleted_at=null;
    insert into public.shop_settings(shop_id,allow_same_day,max_days_advance,cancel_hours,buffer_minutes,require_deposit,deposit_amount_cents,late_grace_minutes,no_show_strike_limit,reminder_24_hours,reminder_2_hours,reminder_custom_enabled,reminder_custom_minutes) values(v_shop_id,coalesce((v_shop#>>'{bookingPolicy,allowSameDay}')::boolean,true),coalesce((v_shop#>>'{bookingPolicy,maxDaysAdvance}')::integer,30),coalesce((v_shop#>>'{bookingPolicy,cancelHours}')::integer,24),coalesce((v_shop#>>'{bookingPolicy,bufferMinutes}')::integer,0),coalesce((v_shop#>>'{bookingPolicy,requireDeposit}')::boolean,false),round(coalesce((v_shop#>>'{bookingPolicy,depositAmount}')::numeric,0)*100)::integer,coalesce((v_shop#>>'{bookingPolicy,lateGraceMinutes}')::integer,10),coalesce((v_shop#>>'{bookingPolicy,noShowStrikeLimit}')::integer,2),coalesce((v_shop#>>'{bookingPolicy,reminder24Hours}')::boolean,true),coalesce((v_shop#>>'{bookingPolicy,reminder2Hours}')::boolean,true),coalesce((v_shop#>>'{bookingPolicy,reminderCustomEnabled}')::boolean,false),coalesce((v_shop#>>'{bookingPolicy,reminderCustomMinutes}')::integer,60)) on conflict(shop_id) do update set allow_same_day=excluded.allow_same_day,max_days_advance=excluded.max_days_advance,cancel_hours=excluded.cancel_hours,buffer_minutes=excluded.buffer_minutes,require_deposit=excluded.require_deposit,deposit_amount_cents=excluded.deposit_amount_cents,late_grace_minutes=excluded.late_grace_minutes,no_show_strike_limit=excluded.no_show_strike_limit,reminder_24_hours=excluded.reminder_24_hours,reminder_2_hours=excluded.reminder_2_hours,reminder_custom_enabled=excluded.reminder_custom_enabled,reminder_custom_minutes=excluded.reminder_custom_minutes;
  end loop;
  for v_user in select e.value from jsonb_array_elements(coalesce(snapshot->'users','[]'::jsonb)) e(value) loop if coalesce(v_user->>'shopId','')<>'' and coalesce(v_user->>'role','') in ('owner','barber') then select l.target_id into v_shop_id from public.legacy_source_ids l where l.entity_type='shop' and l.source_id=v_user->>'shopId'; select l.target_id into v_user_id from public.legacy_source_ids l where l.entity_type='user' and l.source_id=coalesce(nullif(v_user->>'id',''),v_user->>'username'); if v_shop_id is not null and v_user_id is not null then v_source:=(v_user->>'shopId')||':'||(v_user->>'username'); v_member_id:=public.slotzy_legacy_target_id('member',v_source); insert into public.shop_members(id,shop_id,user_id,role) values(v_member_id,v_shop_id,v_user_id,(v_user->>'role')::public.membership_role) on conflict(id) do update set shop_id=excluded.shop_id,user_id=excluded.user_id,role=excluded.role,deleted_at=null; end if; end if; end loop;
  for v_service in select e.value from jsonb_array_elements(coalesce(snapshot->'services','[]'::jsonb)) e(value) loop v_source:=v_service->>'id';v_service_id:=public.slotzy_legacy_target_id('service',v_source);select l.target_id into v_shop_id from public.legacy_source_ids l where l.entity_type='shop' and l.source_id=v_service->>'shopId';insert into public.services(id,shop_id,name,price_cents,duration_minutes,is_active) values(v_service_id,v_shop_id,coalesce(v_service->>'name',v_service->>'title'),round(coalesce((v_service->>'price')::numeric,0)*100)::integer,coalesce((v_service->>'durationMinutes')::integer,(v_service->>'duration')::integer,30),coalesce((v_service->>'active')::boolean,true)) on conflict(id) do update set shop_id=excluded.shop_id,name=excluded.name,price_cents=excluded.price_cents,duration_minutes=excluded.duration_minutes,is_active=excluded.is_active,deleted_at=null;v_provider_source:=(v_service->>'shopId')||':'||coalesce(v_service->>'barberUsername',v_service->>'ownerUsername');select l.target_id into v_member_id from public.legacy_source_ids l where l.entity_type='member' and l.source_id=v_provider_source;if v_member_id is not null then insert into public.provider_services(provider_member_id,service_id,is_active) values(v_member_id,v_service_id,coalesce((v_service->>'active')::boolean,true)) on conflict(provider_member_id,service_id) do update set is_active=excluded.is_active;end if;end loop;
  for v_username,v_schedule in select e.key,e.value from jsonb_each(coalesce(snapshot->'availability','{}'::jsonb)) e(key,value) loop select l.target_id into v_member_id from public.legacy_source_ids l where l.entity_type='member' and l.source_id like '%:'||v_username order by l.is_canonical desc limit 1;if v_member_id is null then continue;end if;for v_time_off in select e.value from jsonb_array_elements(coalesce(v_schedule->'timeOff','[]'::jsonb)) e(value) loop v_source:=coalesce(nullif(v_time_off->>'id',''),v_username||':'||(v_time_off->>'startISO')||':'||(v_time_off->>'endISO'));insert into public.time_off(id,provider_member_id,starts_at,ends_at,note) values(public.slotzy_legacy_target_id('time_off',v_source),v_member_id,(v_time_off->>'startISO')::timestamptz,(v_time_off->>'endISO')::timestamptz,v_time_off->>'note') on conflict(id) do update set provider_member_id=excluded.provider_member_id,starts_at=excluded.starts_at,ends_at=excluded.ends_at,note=excluded.note;end loop;for v_day_name,v_day_schedule in select e.key,e.value from jsonb_each(coalesce(v_schedule->'weekly','{}'::jsonb)) e(key,value) loop insert into public.availability(provider_member_id,weekday,is_enabled,start_time,end_time,timezone,buffer_minutes) values(v_member_id,case v_day_name when 'sun' then 0 when 'mon' then 1 when 'tue' then 2 when 'wed' then 3 when 'thu' then 4 when 'fri' then 5 else 6 end,coalesce((v_day_schedule->>'enabled')::boolean,false),coalesce((v_day_schedule->>'start')::time,time '09:00'),coalesce((v_day_schedule->>'end')::time,time '17:00'),coalesce(nullif(v_day_schedule->>'timezone',''),nullif(v_schedule->>'timezone',''),'America/Chicago'),coalesce((v_day_schedule->>'bufferMinutes')::integer,(v_schedule->>'bufferMinutes')::integer,0)) on conflict(provider_member_id,weekday) do update set is_enabled=excluded.is_enabled,start_time=excluded.start_time,end_time=excluded.end_time,timezone=excluded.timezone,buffer_minutes=excluded.buffer_minutes;end loop;end loop;
  for v_booking in select e.value from jsonb_array_elements(coalesce(snapshot->'bookings','[]'::jsonb)) e(value) loop v_source:=v_booking->>'id';v_booking_id:=public.slotzy_legacy_target_id('booking',v_source);select l.target_id into v_shop_id from public.legacy_source_ids l where l.entity_type='shop' and l.source_id=v_booking->>'shopId';v_provider_source:=(v_booking->>'shopId')||':'||coalesce(v_booking->>'barberUsername',v_booking->>'ownerUsername');select l.target_id into v_member_id from public.legacy_source_ids l where l.entity_type='member' and l.source_id=v_provider_source;select l.target_id into v_service_id from public.legacy_source_ids l where l.entity_type='service' and l.source_id=v_booking->>'serviceId';if v_service_id is null then select l.target_id into v_service_id from public.legacy_source_ids l join public.services s on s.id=l.target_id where l.entity_type='service' and s.shop_id=v_shop_id and s.name=coalesce(v_booking->>'serviceName',v_booking->>'serviceTitle') limit 1;end if;v_starts:=coalesce(nullif(v_booking->>'startISO','')::timestamptz,((v_booking->>'date')||'T'||(v_booking->>'time'))::timestamptz);v_duration:=coalesce((v_booking->>'durationMinutes')::integer,(v_booking->>'duration')::integer,30);v_ends:=coalesce(nullif(v_booking->>'endISO','')::timestamptz,v_starts+make_interval(mins=>v_duration));insert into public.bookings(id,shop_id,provider_member_id,service_id,client_name,client_email,client_phone,client_contact,start_at,end_at,timezone,duration_minutes,status,confirmation_code,deposit_required,deposit_amount_cents,deposit_status,cancelled_at,policy_snapshot,service_snapshot) values(v_booking_id,v_shop_id,v_member_id,v_service_id,v_booking->>'clientName',nullif(v_booking->>'clientEmail','')::citext,nullif(v_booking->>'clientPhone',''),v_booking->>'clientContact',v_starts,v_ends,coalesce(nullif(v_booking->>'timezone',''),'America/Chicago'),v_duration,coalesce((v_booking->>'status')::public.booking_status,'booked'),coalesce(nullif(v_booking->>'confirmationCode',''),upper(right(replace(v_source,'-',''),6)),'N/A'),coalesce((v_booking->>'depositRequired')::boolean,false),round(coalesce((v_booking->>'depositAmount')::numeric,0)*100)::integer,coalesce((v_booking->>'depositStatus')::public.deposit_status,'not_required'),case when v_booking->>'status'='cancelled' then now() else null end,coalesce(v_booking->'policySnapshot','{}'::jsonb),jsonb_build_object('name',coalesce(v_booking->>'serviceName',v_booking->>'serviceTitle','Service'))) on conflict(id) do update set shop_id=excluded.shop_id,provider_member_id=excluded.provider_member_id,service_id=excluded.service_id,start_at=excluded.start_at,end_at=excluded.end_at,duration_minutes=excluded.duration_minutes,status=excluded.status,confirmation_code=excluded.confirmation_code,client_name=excluded.client_name,client_email=excluded.client_email,client_phone=excluded.client_phone,client_contact=excluded.client_contact,timezone=excluded.timezone,deposit_required=excluded.deposit_required,deposit_amount_cents=excluded.deposit_amount_cents,deposit_status=excluded.deposit_status,cancelled_at=excluded.cancelled_at,policy_snapshot=excluded.policy_snapshot,service_snapshot=excluded.service_snapshot;end loop;
end;
$$;

grant usage on schema public to service_role;
grant select, insert, update, delete on table public.users, public.shops, public.shop_members, public.shop_settings, public.services, public.provider_services, public.availability, public.time_off, public.bookings, public.booking_events, public.booking_manage_tokens, public.email_outbox, public.legacy_source_ids, public.slotzy_test_control to service_role;
revoke all on function public.slotzy_legacy_target_id(text, text) from public;
revoke all on function public.slotzy_storage_write_snapshot(jsonb) from public;
revoke all on function public.slotzy_reset_disposable_test_data(text) from public;
revoke all on function public.slotzy_create_booking(jsonb) from public;
grant execute on function public.slotzy_legacy_target_id(text, text), public.slotzy_storage_write_snapshot(jsonb), public.slotzy_reset_disposable_test_data(text), public.slotzy_create_booking(jsonb) to service_role;
commit;
